// Builds a superprod-connect request from msg.payload.
// Accepted fields: title (required), project, notes, url, plannedDate, deadline.
// Set the variables in the tab properties (double-click the "Super Productivity" tab).
const input = msg.payload || {};

// Today in local time; used when no plannedDate is given and PLAN_FOR_TODAY is "true"
const now = new Date();
const today = [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, "0"),
    String(now.getDate()).padStart(2, "0"),
].join("-");

const baseUrl = String(env.get("SUPERPROD_CONNECT_URL") || "").replace(/\/+$/, "");
const token = String(env.get("SUPERSYNC_TOKEN") || "").replace(/\s+/g, "");
const e2eeKey = env.get("SUPERSYNC_E2EE_KEY");

if (!baseUrl || !token) {
    node.error("Set SUPERPROD_CONNECT_URL and SUPERSYNC_TOKEN in the tab properties", msg);
    return null;
}

msg.method = "POST";
msg.url = baseUrl + "/tasks";
msg.headers = {
    "Authorization": "Bearer " + token,
    "Content-Type": "application/json"
};
if (e2eeKey) msg.headers["X-Encryption-Key"] = e2eeKey;

msg.payload = {
    title: input.title,
    project: input.project || env.get("SUPERPROD_PROJECT") || undefined,
    notes: input.notes,
    url: input.url,
    plannedDate: input.plannedDate || (env.get("PLAN_FOR_TODAY") === "true" ? today : undefined),
    deadline: input.deadline
};

return msg;
